const pos={woman:'start',respondent:'start'};
const overviewStages=[
  {title:'Complaint submission',section:'Section 9; Central Rule 7(1), where applicable',time:'Within 3 months of the incident or last relevant incident; extension up to 3 further months may be granted with reasons recorded. Under applicable Central Rule 7(1), submit six copies with supporting documents and witness names and addresses to the competent Committee.'},
  {title:'Preliminary review, forum & confidentiality',section:'Sections 4, 6, 7, 9 and 16; Central Rule 7(4), where applicable',time:'Verify the competent IC/LC, Committee constitution, potential conflicts and complaint requirements. Explain confidentiality and record institutional undertakings (NDA), where used; an NDA is not a statutory condition for filing a complaint and must preserve lawful reporting and remedies.'},
  {title:'Voluntary conciliation, if requested',section:'Section 10',time:'Only before initiation of inquiry, at the aggrieved woman’s request. No pressure to settle; monetary settlement cannot be its basis.',guidance:[{title:'Possible non-monetary terms',text:'If freely agreed and lawful: a written apology, a non-repetition undertaking, or professional-contact boundaries. These are illustrative options, not a statutory checklist.'}]},
  {title:'Complaint copy and respondent reply',section:'Central Rule 7(2)–(3), where applicable',time:'Send complaint copy within 7 working days of receipt; respondent reply within 10 working days of receiving prescribed documents.'},
  {title:'Inquiry and hearings',section:'Section 11(1) — procedure; Section 11(4) — time limit',time:'Follow applicable service rules or the prescribed inquiry procedure. Complete the inquiry within 90 days.'},
  {title:'Witness examination & appreciation of evidence',section:'Section 11(3); Central Rule 7(4), where applicable',time:'Part of the 90-day inquiry; no separate fixed statutory deadline.'},
  {title:'Findings, representations and inquiry report',section:'Section 11(1), second proviso; Section 13(1)–(3)',time:'Where both parties are employees, hear both and share findings during the inquiry to enable representations before the Committee. Section 11(1) sets no fixed representation period. Provide the completed report to the employer / District Officer within 10 days of inquiry completion, and make it available to concerned parties.'},
  {title:'Action on recommendations',section:'Section 13(4)',time:'Employer / District Officer to act within 60 days of receipt of recommendations.'},
  {title:'Appeal and post-report rights',section:'Section 18',time:'Appeal period: 90 days from recommendations, subject to the applicable forum and service-rule pathway. The LC is not an appellate authority over the IC.'}
];
const stageExamples=[
 'An employee describes alleged unwelcome remarks, identifies the relevant dates and submits a written complaint to the competent Committee.',
 'Before scheduling hearings, the Committee checks its constitution, the appropriate forum and any member conflict, and explains confidentiality.',
 'Before inquiry starts, the woman requests conciliation and freely proposes an apology and professional-contact boundaries, without monetary settlement as the basis.',
 'After receiving the prescribed complaint documents, the respondent prepares a factual reply with supporting documents and witness details under the applicable rules.',
 'The Committee gives both sides an opportunity to be heard and records proceedings without deciding the outcome in advance.',
 'A witness describes what they personally observed. The Committee considers that account alongside messages and the parties’ explanations, rather than treating an allegation as proof.',
 'Where both parties are employees, the Committee shares findings for representations during the inquiry, considers them and prepares its reasoned report.',
 'The employer receives the recommendations, considers the action required and records implementation within the applicable statutory period.',
 'A party considering an appeal checks the competent forum and relevant dates instead of assuming the Local Committee can hear an appeal against an IC.'
];
let showAll=false;
let readingStep=0;
try{const saved=Number(localStorage.getItem('posh-reading-size'));if(Number.isInteger(saved)&&saved>=0&&saved<=2)readingStep=saved;}catch{}
function applyReadingSize(){
 document.documentElement.style.setProperty('--reading-scale',String(1+readingStep*.1));
 document.getElementById('reading-size').textContent=(100+readingStep*10)+'%';
 document.querySelector('[data-reading="smaller"]').disabled=readingStep===0;
 document.querySelector('[data-reading="larger"]').disabled=readingStep===2;
}
applyReadingSize();
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-reading]');if(!button)return;
 readingStep=button.dataset.reading==='reset'?0:Math.max(0,Math.min(2,readingStep+(button.dataset.reading==='larger'?1:-1)));
 applyReadingSize();try{localStorage.setItem('posh-reading-size',String(readingStep));}catch{}
});
const h=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
